  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Leadership and Teamwork$j$, $j${"readings": [{"title": "Mark 10 (King James Version)", "url": "/portal/bible/Mark/10"}], "body": "Leadership is influencing people toward a good goal. Mark 10:43 and 44 says, whosoever will be great among you, shall be your minister: And whosoever of you will be the chiefest, shall be servant of all. Christian leadership begins with service.\n\nGood leaders have a clear vision, communicate well, set an example, listen, make wise decisions, admit mistakes and develop others. A vision is a picture of what the business is working toward. A mission is a short statement of why the business exists and whom it serves. Values are the principles that guide behavior, such as honesty, excellence and compassion. Write them down and live them.\n\nTeams succeed when people know their roles, trust one another and share the goal. First Corinthians 12:12 compares the church to a body with many members, and a team works the same way. Healthy teams meet regularly, give honest feedback kindly, celebrate wins and solve conflicts early. Conflict is normal. Resolve it by listening, stating the problem without blame, looking for common ground and agreeing on a fair solution. Matthew 18:15 teaches going to the person privately first.\n\nDelegation means giving a task to another person with clear instructions and trust. Good delegation frees the leader to focus on what only the leader can do. Provide the needed resources, set deadlines, check in and give credit.\n\nDecision making improves with a process: define the problem, gather facts, list options, weigh results, pray and seek counsel, decide and review.\n\nYour task: (1) Define vision, mission and values. (2) Write a mission statement for your idea. (3) Describe how you would resolve a conflict on a team.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Mark 10:43 and 44 says, whosoever will be great among you, shall be your minister. Christian leadership begins with service.\n\nNow watch this. Leaders have a vision, communicate clearly, set an example, listen and admit mistakes. A vision is a picture of where the business is going. A mission states why it exists and whom it serves. Values are the principles that guide behavior. Write them down and live them.\n\nTeams succeed when people know their roles, trust one another and share the goal. First Corinthians 12:12 compares the church to a body with many members. Resolve conflict by listening, naming the problem without blame and finding a fair solution. Matthew 18:15 says to go to the person privately first.\n\nDelegation means giving a task with clear instructions and trust.\n\nYour task is to define three terms, write a mission statement and describe how to resolve a conflict. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Leadership and Teamwork$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Hiring, Wages and Workplace Rules$j$, $j${"readings": [{"title": "Leviticus 19 (King James Version)", "url": "/portal/bible/Leviticus/19"}], "body": "When a business grows, it may need help. Hiring is a serious responsibility. This lesson is general education and not legal advice. An employer should consult the U.S. Department of Labor, the Florida Department of Commerce and a licensed attorney. Leviticus 19:13 says, the wages of him that is hired shall not abide with thee all night until the morning, and Deuteronomy 24:14 and 15 teaches fair and timely pay for workers.\n\nAn employee works under the direction of the business and receives wages or a salary, with taxes withheld by the employer. An independent contractor is in business for themselves, controls how the work is done and is paid for a project. The two are treated differently by tax and labor law, and labeling a worker incorrectly can cause legal trouble. The federal Fair Labor Standards Act sets minimum wage and overtime rules. Florida has its own minimum wage, which is adjusted over time, so check the current rate. Employers must verify that workers are legally allowed to work, keep payroll records, withhold the proper taxes, carry required insurance such as workers compensation when applicable and provide a safe workplace.\n\nChild labor laws limit the hours and types of work for people under eighteen. Younger workers cannot do dangerous tasks, and there are limits on work during school hours. Parents or family members working in a family business may be treated differently under some rules, so ask the Department of Labor.\n\nTreat every worker with respect. Do not discriminate or harass. Write clear job descriptions, expectations and pay. Pay on time, thank people and pay a fair wage. Colossians 4:1 says, Masters, give unto your servants that which is just and equal.\n\nYour task: (1) Compare an employee and an independent contractor. (2) List five duties of an employer. (3) Explain why fair and timely pay matters.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Leviticus 19:13 says, the wages of him that is hired shall not abide with thee all night until the morning. Colossians 4:1 says, give unto your servants that which is just and equal. This lesson is general education, not legal advice.\n\nNow watch this. An employee works under the direction of the business and has taxes withheld. An independent contractor controls how the work is done and is paid for a project. Mislabeling a worker can cause legal trouble.\n\nEmployers must follow minimum wage and overtime rules, verify that workers may legally work, keep payroll records, withhold taxes, carry required insurance and provide a safe workplace. Child labor laws limit hours and tasks for people under eighteen.\n\nTreat every worker with respect, write clear expectations and pay on time.\n\nYour task is to compare two worker types, list five employer duties and explain fair pay. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Hiring, Wages and Workplace Rules$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Growth, Risk and Wise Decisions$j$, $j${"readings": [{"title": "Proverbs 24 (King James Version)", "url": "/portal/bible/Proverbs/24"}], "body": "Growth can be good, but it must be wise. Proverbs 21:5 says, The thoughts of the diligent tend only to plenty; but of every one that is hasty only to want. Many businesses fail not because the idea is bad but because they grow faster than their systems, cash or character can handle.\n\nGrowth paths include selling more to current customers, finding new customers, adding new products or services, opening a new location, selling online, forming partnerships and franchising, which is licensing your business model to others. Each path has costs and risks. Before you grow, ask: Is the current business profitable? Do I have the cash, people and systems? What is the worst that can happen? Can I recover from it?\n\nRisk management means identifying risks and reducing them. Common risks include loss of key customers, a supplier failure, legal claims, theft, injury, natural disaster, illness and changes in the economy. Responses include insurance, savings reserves, contracts, backups, training and avoiding unnecessary danger. Insurance transfers part of the risk to an insurer in exchange for a premium. A reserve is money set aside for emergencies. Diversification means not depending on only one customer or product.\n\nFailure is possible. Proverbs 24:16 says, a just man falleth seven times, and riseth up again. When a business fails, pay honest debts, learn the lessons, thank those who helped and try again with greater wisdom. Character is more important than any single business.\n\nUse measures to guide decisions. Common ones are monthly revenue, profit margin, customer count, repeat customers and customer satisfaction. Review them regularly.\n\nYour task: (1) Define franchise, insurance and reserve. (2) List three risks for your idea and a plan for each. (3) Name five measures you will track.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Proverbs 21:5 says, The thoughts of the diligent tend only to plenty; but of every one that is hasty only to want. Many businesses fail because they grow faster than their systems, cash or character can handle.\n\nNow watch this. Growth paths include selling more to current customers, finding new customers, adding products, opening a location, selling online, forming partnerships and franchising. Before growing, ask whether the business is profitable, whether you have the cash, people and systems, and what the worst outcome could be.\n\nRisk management means identifying and reducing risks. Use insurance, reserves, contracts, backups and training. Diversification means not depending on one customer or product.\n\nProverbs 24:16 says, a just man falleth seven times, and riseth up again. If a business fails, pay honest debts, learn and try again wisely.\n\nTrack revenue, profit margin, customers, repeat customers and satisfaction.\n\nYour task is to define three terms, plan for three risks and name five measures. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Growth, Risk and Wise Decisions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Generosity, Ministry and Social Impact$j$, $j${"readings": [{"title": "2 Corinthians 9 (King James Version)", "url": "/portal/bible/2Corinthians/9"}], "body": "A business can bless more than its owner. Second Corinthians 9:7 says, God loveth a cheerful giver. Malachi 3:10 invites God's people to bring tithes into the storehouse, and Proverbs 3:9 says, Honour the LORD with thy substance, and with the firstfruits of all thine increase. Stewardship means managing what God entrusts to us, including money, time, talent and influence.\n\nWays a business can give include tithes and offerings, sponsoring a church or school event, donating products or services, paying fair wages, hiring people who need opportunity, mentoring young people and serving the community. Giving should be honest and planned. Set a percentage, keep records of donations, and learn the rules. A gift to a qualified nonprofit may be tax deductible, but a business owner should ask a tax professional how it works. Do not give in order to be praised by people. Matthew 6:3 and 4 teaches that giving should be done in secret.\n\nA business can be a ministry in several ways. It can create jobs, provide excellent and honest products, treat people with dignity, share a testimony through the way it works and support missions. It should never pressure customers or workers about religion, and it must follow laws about discrimination and religious freedom. A faith based nonprofit or ministry may have special legal and tax requirements, so seek professional advice.\n\nSocial enterprise is a business whose main purpose is to solve a social problem while earning income. Examples include a program that trains young people for jobs or a store whose profits support a shelter.\n\nBalance matters. Do not neglect family, rest or worship for the sake of the business. Mark 8:36 asks, For what shall it profit a man, if he shall gain the whole world, and lose his own soul?\n\nYour task: (1) Define stewardship and social enterprise. (2) Design a giving plan for your idea. (3) Explain Mark 8:36 in your own words.\n\nFlorida standards: BE.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "BE.912", "script": "Welcome back. Listen, Second Corinthians 9:7 says, God loveth a cheerful giver. Proverbs 3:9 says, Honour the LORD with thy substance, and with the firstfruits of all thine increase.\n\nNow watch this. Stewardship means managing what God entrusts to us, including money, time, talent and influence. A business can give through tithes and offerings, sponsoring events, donating products or services, paying fair wages, hiring those who need opportunity and mentoring young people. Plan your giving, keep records and ask a tax professional about deductions. Matthew 6:3 and 4 says give in secret.\n\nA business can be a ministry by creating jobs, providing honest products and treating people with dignity. It must never pressure anyone about religion and must follow the law. A social enterprise earns income while solving a social problem.\n\nMark 8:36 asks what it profits to gain the whole world and lose your soul.\n\nYour task is to define two terms, design a giving plan and explain Mark 8:36. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Generosity, Ministry and Social Impact$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Leadership, Employment, Growth and Generosity$j$, $j${"prompt": "Write a report of at least 250 words. Use complete sentences and label each part. Mark 10:43 and 44 says, whosoever will be great among you, shall be your minister: And whosoever of you will be the chiefest, shall be servant of all.\n\nPart 1: Define vision, mission and values, write a mission statement for a business idea and describe how to resolve a conflict on a team.\nPart 2: Compare an employee and an independent contractor, list five duties of an employer and explain child labor limits. Note that this is general education and not legal advice.\nPart 3: Describe three growth paths, three risks and how insurance, reserves and diversification reduce risk.\nPart 4: Create a giving plan for your business using Proverbs 3:9 and Second Corinthians 9:7, and explain how a business can be a ministry without pressuring anyone.\nPart 5: Explain Mark 8:36 and how an owner keeps balance among family, rest, worship and work.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Leadership, Employment, Growth and Generosity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Honour the LORD with Thy Substance$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a leader you admire and what makes that person a servant leader, (2) explains how you would treat employees fairly if you owned a business, (3) explains how a business can give back without seeking praise, and (4) connects your answer to Mark 10:43 and 44, Proverbs 3:9 or Second Corinthians 9:7. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a business honor God without pressuring people? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Honour the LORD with Thy Substance$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Leadership and Teamwork$j$, $j${"questions": [{"q": "According to Mark 10:43 and 44, the greatest leader is a:", "options": ["Boss only", "Critic", "Servant", "Competitor"]}, {"q": "A mission statement tells:", "options": ["The tax rate", "Why the business exists and whom it serves", "The price list", "The logo color"]}, {"q": "Delegation means:", "options": ["Avoiding work", "Doing everything alone", "Blaming others", "Giving a task with clear instructions and trust"]}, {"q": "Matthew 18:15 teaches to go to the person:", "options": ["Online", "Never", "Publicly", "Privately first"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Leadership and Teamwork$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,3}'::int[], array[$j$Christian leadership is service.$j$,$j$Missions give purpose.$j$,$j$Delegation develops others.$j$,$j$Private, respectful correction comes first.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Leadership and Teamwork$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Hiring, Wages and Workplace Rules$j$, $j${"questions": [{"q": "An independent contractor:", "options": ["Never gets paid", "Controls how the work is done", "Is always an employee", "Has taxes withheld by default"]}, {"q": "Leviticus 19:13 teaches that wages should be:", "options": ["Delayed", "Reduced secretly", "Hidden", "Paid promptly"]}, {"q": "Child labor laws:", "options": ["Allow dangerous work", "Apply only to adults", "Do not exist", "Limit hours and tasks for people under eighteen"]}, {"q": "An employer should:", "options": ["Ignore insurance", "Hide wages", "Keep payroll records and provide a safe workplace", "Skip taxes"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Hiring, Wages and Workplace Rules$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,2}'::int[], array[$j$Contractors are in business for themselves.$j$,$j$God cares about fair, timely pay.$j$,$j$Young workers are protected.$j$,$j$Employer duties protect everyone.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Hiring, Wages and Workplace Rules$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Growth, Risk and Wise Decisions$j$, $j${"questions": [{"q": "Insurance:", "options": ["Transfers part of a risk to an insurer for a premium", "Removes all risk", "Is a loan", "Is a tax"]}, {"q": "A reserve is:", "options": ["A logo", "A kind of sale", "Money set aside for emergencies", "A competitor"]}, {"q": "Diversification means:", "options": ["Avoiding customers", "Raising prices", "Not depending on only one customer or product", "Selling one item only"]}, {"q": "Proverbs 24:16 says a just man falleth seven times and:", "options": ["Gives up", "Hides", "Riseth up again", "Stays down"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Growth, Risk and Wise Decisions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,2}'::int[], array[$j$Premiums buy protection.$j$,$j$Reserves help a business survive hard times.$j$,$j$Spreading risk helps stability.$j$,$j$Resilience is a virtue.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Growth, Risk and Wise Decisions$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Generosity, Ministry and Social Impact$j$, $j${"questions": [{"q": "Stewardship means:", "options": ["Managing what God entrusts to us", "Avoiding giving", "Ignoring records", "Owning everything"]}, {"q": "Second Corinthians 9:7 says God loveth a:", "options": ["Cheerful giver", "Hasty buyer", "Silent worker", "Fast seller"]}, {"q": "A social enterprise:", "options": ["Never earns income", "Earns income while solving a social problem", "Is a hobby", "Is illegal"]}, {"q": "A business owner should not:", "options": ["Pressure customers or workers about religion", "Give generously", "Pay fair wages", "Keep records"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Generosity, Ministry and Social Impact$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,0}'::int[], array[$j$Stewards manage for the owner.$j$,$j$Giving should be cheerful.$j$,$j$It combines mission and revenue.$j$,$j$Respect people and follow the law.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Generosity, Ministry and Social Impact$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Leadership, Employment, Growth and Generosity$j$, $j${"questions": [{"q": "A vision is:", "options": ["A tax form", "A price", "A picture of where the business is going", "A supplier"]}, {"q": "Values are:", "options": ["Products", "Profits", "Prices", "Principles that guide behavior"]}, {"q": "An employee differs from a contractor because the employee:", "options": ["Is always unpaid", "Has no tax withholding ever", "Works under the employer's direction", "Sets all terms alone"]}, {"q": "Wages should be paid:", "options": ["Late", "Fairly and on time", "Never", "In secret"]}, {"q": "Franchising is:", "options": ["Licensing your business model to others", "Buying inventory", "Closing a business", "Paying taxes"]}, {"q": "Insurance requires paying a:", "options": ["Dividend", "Tithe", "Premium", "Grant"]}, {"q": "Matthew 6:3 and 4 teaches that giving should be:", "options": ["Delayed", "Advertised", "In secret", "Forced"]}, {"q": "Mark 8:36 asks what it profits to gain the world and lose:", "options": ["His own soul", "His friends", "His map", "His job"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Leadership, Employment, Growth and Generosity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,1,0,2,2,0}'::int[], array[$j$Vision gives direction.$j$,$j$Values guide decisions.$j$,$j$Direction and control matter.$j$,$j$Leviticus 19:13 and Deuteronomy 24:14 and 15.$j$,$j$Franchises copy a proven model.$j$,$j$Premiums buy coverage.$j$,$j$Give without seeking praise.$j$,$j$Soul matters more than gain.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Leadership, Employment, Growth and Generosity$j$ on conflict (item_id) do nothing;
